// Match only schemas generated by this command. No prefix-only or search-path list.
var isolatedSchemaPattern = regexp.MustCompile(`^learner_regression_[0-9]{8}_[0-9]{6}_[a-f0-9]{16}$`)

func loadVault() (*credential.Vault, error) {
	key, err := base64.StdEncoding.DecodeString(os.Getenv("CREDENTIAL_KEY"))
	if err != nil || len(key) != 32 {
		return nil, errors.New("valid CREDENTIAL_KEY required for execute")
	}
	defer clear(key)
	vault, err := credential.New(key)
	if err != nil {
		return nil, errors.New("credential vault unavailable")
	}
	return vault, nil
}

func courseDigest(courses []course) string {
	raw, _ := json.Marshal(courses)
	digest := sha256.Sum256(raw)
	return hex.EncodeToString(digest[:])
}

func loadResumeManifest(dir string) (manifest, []caseResult, error) {
	var m manifest
	raw, err := os.ReadFile(filepath.Join(dir, "manifest.json"))
	if err != nil || json.Unmarshal(raw, &m) != nil {
		return m, nil, errors.New("cannot read retained manifest")
	}
	if !isolatedSchemaPattern.MatchString(m.TargetSchema) || len(m.Courses) == 0 {
		return m, nil, errors.New("resume manifest must name an existing isolated schema and nonempty frozen courses")
	}
	if m.Mode != "executing" && m.Mode != "interrupted" && m.Mode != "completed" {
		return m, nil, errors.New("resume requires a fully cloned regression, not dry-run or preparing state")
	}
	keys := map[string]bool{}
	for _, c := range m.Courses {
		if c.Owner == "" || c.Connection == "" || c.ID == "" || c.Ref == "" || c.Record == "" || (c.Source != "chaoxing" && c.Source != "mooc") || keys[c.ID] {
			return m, nil, errors.New("invalid or duplicate frozen course")
		}
		keys[c.ID] = true
	}
	if m.CourseDigest != "" && m.CourseDigest != courseDigest(m.Courses) {
		return m, nil, errors.New("frozen manifest courses changed")
	}
	frozen, err := os.ReadFile(filepath.Join(dir, "courses.frozen.private.json"))
	if err == nil {
		var courses []course
		if json.Unmarshal(frozen, &courses) != nil || !reflect.DeepEqual(courses, m.Courses) {
			return m, nil, errors.New("manifest differs from immutable frozen course list")
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return m, nil, errors.New("cannot inspect frozen course list")
	}
	var results []caseResult
	raw, err = os.ReadFile(filepath.Join(dir, "results.private.json"))
	if err == nil {
		if json.Unmarshal(raw, &results) != nil {
			return m, nil, errors.New("invalid retained results")
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return m, nil, errors.New("cannot read retained results")
	}
	seen := map[string]bool{}
	for _, r := range results {
		if !keys[r.OfferingID] || seen[r.OfferingID] {
			return m, nil, errors.New("results do not match unique frozen cases")
		}
		seen[r.OfferingID] = true
	}
	return m, results, nil
}

func assertSchema(ctx context.Context, conn *pgx.Conn, schema string) error {
	if !isolatedSchemaPattern.MatchString(schema) {
		return errors.New("invalid target schema")
	}
	var actual string
	if err := conn.QueryRow(ctx, "SELECT current_schema()").Scan(&actual); err != nil || actual != schema {
		return errors.New("isolated target schema verification failed; target must exist")
	}
	return nil
}

func verifyFrozenCourses(ctx context.Context, conn *pgx.Conn, courses []course) error {
	for _, c := range courses {
		var actual course
		err := conn.QueryRow(ctx, `SELECT user_id,connection_id,source,id,course_ref,name,record_id::text FROM academic_offerings WHERE user_id=$1 AND connection_id=$2 AND id=$3`, c.Owner, c.Connection, c.ID).Scan(&actual.Owner, &actual.Connection, &actual.Source, &actual.ID, &actual.Ref, &actual.Name, &actual.Record)
		if err != nil || actual != c {
			return errors.New("isolated course data differs from frozen manifest; resume refused")
		}
	}
	return nil
}

func resume(ctx context.Context, o options) error {
	if !o.execute {
		return errors.New("--resume-dir requires explicit --execute; no model or database action performed")
	}
	if o.owner != "" || o.round != "" || o.allowActiveSnapshot {
		return errors.New("resume uses its immutable manifest; owner/round/allow-active-snapshot cannot change it")
	}
	if o.timeout <= 0 {
		return errors.New("invalid course timeout")
	}
	dir, err := filepath.Abs(o.resumeDir)
	if err != nil {
		return errors.New("invalid resume directory")
	}
	info, err := os.Lstat(dir)
	if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
		return errors.New("resume directory must be an existing real directory")
	}
	release, err := lockDirectory(dir)
	if err != nil {
		return err
	}
	defer release()
	m, prior, err := loadResumeManifest(dir)
	if err != nil {
		return err
	}
	dsn, err := isolatedDSN(os.Getenv("DATABASE_URL"), m.TargetSchema)
	if err != nil {
		return err
	}
	// Resume opens only the exact isolated target. No source connection, migration,
	// clone, source activity check, truncation or status rewriting is performed.
	target, err := pgx.Connect(ctx, dsn)
	if err != nil {
		return errors.New("isolated target unavailable")
	}
	defer target.Close(context.Background())
	if err = assertSchema(ctx, target, m.TargetSchema); err != nil {
		return err
	}
	if err = verifyFrozenCourses(ctx, target, m.Courses); err != nil {
		return err
	}
	var active int
	if err = target.QueryRow(ctx, `SELECT count(*) FROM agent_runs WHERE status='running'`).Scan(&active); err != nil {
		return errors.New("cannot inspect isolated running cases")
	}
	if active != 0 {
		return errors.New("isolated schema still has running cases; stop/reconcile that executor before resuming")
	}
	db, err := dbbridge.Open(ctx, dsn)
	if err != nil {
		return errors.New("cannot open isolated repository")
	}
	defer db.Close()
	vault, err := loadVault()
	if err != nil {
		return err
	}
	prompt, err := os.ReadFile(o.prompt)
	if err != nil || len(prompt) == 0 {
		return errors.New("cannot read latest Learner prompt")
	}
	// A v1 directory has no immutable copy. Verify against the untouched target
	// first, then anchor it once. Existing result history is also kept verbatim.
	if err = writeOnce(filepath.Join(dir, "courses.frozen.private.json"), m.Courses); err != nil {
		return err
	}
	if len(prior) > 0 {
		raw, readErr := os.ReadFile(filepath.Join(dir, "results.private.json"))
		if readErr != nil {
			return readErr
		}
		if err = writeBytesOnce(filepath.Join(dir, "results.before-resume.private.json"), raw); err != nil {
			return err
		}
	}
	if err = writeOnce(filepath.Join(dir, "manifest.before-resume.private.json"), m); err != nil {
		return err
	}
	m.CourseDigest = courseDigest(m.Courses)
	m.Mode = "executing"
	digest := sha256.Sum256(prompt)
	m.PromptSHA = hex.EncodeToString(digest[:])
	if err = save(filepath.Join(dir, "manifest.json"), m); err != nil {
		return err
	}
	err = executeCourses(ctx, o, db, target, vault, dir, m, string(prompt), prior)
	if ctx.Err() != nil {
		m.Mode = "interrupted"
	} else {
		m.Mode = "completed"
	}
	if saveErr := save(filepath.Join(dir, "manifest.json"), m); saveErr != nil {
		return saveErr
	}
	return err
}

func lockDirectory(dir string) (func(), error) {
	file, err := os.OpenFile(filepath.Join(dir, "executor.lock"), os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		return nil, errors.New("cannot lock regression directory")
	}
	if syscall.Flock(int(file.Fd()), syscall.LOCK_EX|syscall.LOCK_NB) != nil {
		file.Close()
		return nil, errors.New("regression directory already has an active executor")
	}
	return func() { _ = syscall.Flock(int(file.Fd()), syscall.LOCK_UN); _ = file.Close() }, nil
}

func writeBytesOnce(path string, raw []byte) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if errors.Is(err, os.ErrExist) {
		return nil
	}
	if err != nil {
		return err
	}
	_, writeErr := file.Write(raw)
	syncErr := file.Sync()
	closeErr := file.Close()
	if writeErr != nil {
		return writeErr
	}
	if syncErr != nil {
		return syncErr
	}
	return closeErr
}
func writeOnce(path string, value any) error {
	raw, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return err
	}
	return writeBytesOnce(path, raw)
}

func atomicWrite(path string, raw []byte) error {
	// Destination and staging file are in the same explicitly resolved directory;
	// rename never traverses or replaces a computed parent directory.
	absolute, err := filepath.Abs(path)
	if err != nil {
		return err
	}
	dir := filepath.Dir(absolute)
	resolved, err := filepath.EvalSymlinks(dir)
	if err != nil || resolved != dir {
		return errors.New("artifact parent must be a real resolved directory")
	}
	if info, err := os.Lstat(absolute); err == nil && (!info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0) {
		return errors.New("artifact destination is not a regular file")
	} else if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	file, err := os.CreateTemp(dir, ".artifact-*.tmp")
	if err != nil {
		return err
	}
	temporary := file.Name()
	// temporary is returned by CreateTemp in verified dir; these exact checked
	// files are the only cleanup/rename targets, never the directory itself.
	defer func() { _ = os.Remove(temporary) }()
	if err = file.Chmod(0600); err != nil {
		file.Close()
		return err
	}
	if _, err = file.Write(raw); err != nil {
		file.Close()
		return err
	}
	if err = file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err = file.Close(); err != nil {
		return err
	}
	if filepath.Dir(temporary) != dir {
		return errors.New("staging path escaped artifact directory")
	}
	return os.Rename(temporary, absolute)
}

// Existing writes are never replayed just because the prior model response or
// persistence audit was incomplete. Any same-entity Workflow requires review.
func matchingWorkflow(ctx context.Context, repo f.Repository, c course) (string, error) {
	after := ""
	entity := "source=" + c.Source + "|connection=" + c.Connection + "|course_ref=" + c.Ref
	for {
		page, err := repo.ListWorkflows(ctx, c.Owner, 100, after)
		if err != nil {
			return "", err
		}
		for _, summary := range page {
			w, err := repo.GetWorkflow(ctx, c.Owner, summary.ID)
			if err != nil {
				return "", err
			}
			var def struct {
				Entity struct{ Kind, ID string } `json:"entity"`
			}
			if json.Unmarshal(w.Definition, &def) != nil {
				return "", errors.New("cannot verify existing workflow identity")
			}
			if def.Entity.Kind == "course" && def.Entity.ID == entity {
				return w.ID, nil
			}
		}
		if len(page) < 100 {
			return "", nil
		}
		next := page[len(page)-1].ID
		if next == "" || next == after {
			return "", errors.New("workflow enumeration did not advance")
		}
		after = next
	}
}

func newAttemptID() (string, error) {
	schema, err := newSchema()
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("attempt-%s", schema[len("learner_regression_"):]), nil
}

func executeCourses(ctx context.Context, o options, db *dbbridge.DB, target *pgx.Conn, vault *credential.Vault, dir string, m manifest, prompt string, prior []caseResult) error {
	if err := assertSchema(ctx, target, m.TargetSchema); err != nil {
		return err
	}
	if err := synchronizeLearners(ctx, db, m.Courses, prompt); err != nil {
		return err
	}
	console, err := agentadmin.New(ctx, db.Agents(), db.AgentAdmin(), db.Users(), vault, false, db.AgentData())
	if err != nil {
		return errors.New("cannot load cloned provider settings")
	}
	tracer := &recordingResolver{inner: console.Settings, dir: dir}
	console.Service.Runtime.Resolver = tracer
	agents := map[string]f.AgentInstance{}
	limits := map[string]chan struct{}{}
	for _, c := range m.Courses {
		if _, ok := agents[c.Owner]; ok {
			continue
		}
		a, err := findLearner(ctx, db, c.Owner)
		if err != nil {
			return err
		}
		agents[c.Owner] = a
		limit := a.Limits.Defaults().MaxConcurrent
		if limit > o.parallel {
			limit = o.parallel
		}
		limits[a.ID] = make(chan struct{}, limit)
	}
	attemptID, err := newAttemptID()
	if err != nil {
		return err
	}
	attemptDir := filepath.Join(dir, attemptID)
	if err = os.Mkdir(attemptDir, 0700); err != nil {
		return err
	}
	build, _ := debug.ReadBuildInfo()
	buildDescription := "unavailable"
	if build != nil {
		buildDescription = build.String()
	}
	executableSHA := "unavailable"
	if executable, e := os.Executable(); e == nil {
		if body, e := os.ReadFile(executable); e == nil {
			sum := sha256.Sum256(body)
			executableSHA = hex.EncodeToString(sum[:])
		}
	}
	if err = save(filepath.Join(attemptDir, "attempt.private.json"), map[string]any{"at": time.Now().UTC(), "parallel": o.parallel, "course_manifest_sha256": courseDigest(m.Courses), "prompt_sha256": m.PromptSHA, "target_schema": m.TargetSchema, "executable_sha256": executableSHA, "go_build_info": buildDescription}); err != nil {
		return err
	}
	runner := func(ctx context.Context, index int, c course) caseResult {
		entry := caseResult{OfferingID: c.ID, AttemptID: attemptID, Disposition: "executed"}
		if existing, err := matchingWorkflow(ctx, db.Agents(), c); err != nil {
			entry.ValidationError = "cannot reconcile prior scoped Workflow"
			entry.Error = f.SafeError(err)
			entry.Disposition = "review_required"
			return entry
		} else if existing != "" {
			entry.ValidationError = "existing same-entity Workflow requires review; no model replay performed"
			entry.Disposition = "review_required"
			return entry
		}
		if err := save(filepath.Join(attemptDir, fmt.Sprintf("case-%04d-input.json", index+1)), caseInput(c)); err != nil {
			entry.Error = f.SafeError(err)
			entry.ValidationError = "cannot persist case input"
			return entry
		}
		a := agents[c.Owner]
		raw, _ := json.Marshal(caseInput(c))
		slots := limits[a.ID]
		select {
		case slots <- struct{}{}:
		case <-ctx.Done():
			entry.Error = f.SafeError(ctx.Err())
			entry.ValidationError = "cancelled before agent slot"
			return entry
		}
		defer func() { <-slots }()
		callCtx, cancel := context.WithTimeout(ctx, o.timeout)
		result, callErr := console.Service.Run(callCtx, c.Owner, f.RunRequest{AgentID: a.ID, Trigger: f.UserMessage, Input: raw})
		cancel()
		entry.RunID, entry.Output, entry.Error = result.RunID, result.Output, f.SafeError(callErr)
		cleanup, stop := context.WithTimeout(context.WithoutCancel(ctx), 15*time.Second)
		defer stop()
		if result.RunID != "" {
			if record, readErr := db.Agents().GetRun(cleanup, c.Owner, result.RunID); readErr == nil {
				entry.Record = &record
			}
		}
		entry.Verified, entry.ValidationError = verifyCreation(cleanup, db, c, result.Output, callErr, entry.Record)
		return entry
	}
	return runCases(ctx, o.parallel, dir, attemptDir, m, prior, runner)
}
